    tools\registry\runs\CHECK_ANALYZE_BTH_RENAME_PROPOSALS_PACKAGES_APPS-20260424-014826\packages_apps_bth_occurrences_with_proposals.csv = "tools\registry\runs\CHECK_ANALYZE_BTH_RENAME_PROPOSALS_PACKAGES_APPS-20260424-014826\packages_apps_bth_occurrences_with_proposals.csv"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               = Import-Csv $csvPath
    $filtered = $data | Where-Object { $_.file -like "packages\ui-kit\src\*" -and $_.safe_for_auto_apply -eq "True" }
    $grouped = $filtered | Group-Object file | ForEach-Object {
        $file = $_.Name
        $group = $_.Group
        $isBarrel = ($file -match "index\.ts$|web\.ts$|mobile\.ts$|next\.ts$")
        $hasExport = ($group | Where-Object { $_.line_kind_hint -match "export" }).Count -gt 0
        [PSCustomObject]@{
            File = $file
            SafeOccurrences = $group.Count
            HasExport = $hasExport
            IsBarrel = $isBarrel
        }
    } | Sort-Object SafeOccurrences -Descending
    $grouped | Select-Object -First 20 | Format-Table -AutoSize
